INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明廷在南郊祭祀天地", "description": "明廷在南郊举行祭祀天地的大礼。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年正月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a834a611-9129-5ed2-8dc5-92d2f039bc6b"}, {"title": "朱高炽和朱高煦奉召回京", "description": "朝廷召世子朱高炽与高阳王朱高煦返回京师。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年正月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "76df15a5-4905-565c-9f5a-8366647fdd3b"}, {"title": "明廷赐曾棨等进士及第或出身", "description": "朝廷分别赐曾棨等人进士及第或出身。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年三月乙巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0f8dd916-bb76-5dc8-bd8d-4d7422507606"}, {"title": "永乐朝开始选进士为翰林院庶吉士", "description": "本纪记载，永乐朝开始从进士中选人担任翰林院庶吉士。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年三月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "adeca193-2153-50d2-80da-e13d11820f84"}, {"title": "朱棣要求按被举荐者实际才能决定是否授官", "description": "吏部请求处罚违反规定荐举士人的千户。朱棣举马周因常何举荐而进用为例，主张确有才能便授官，否则停止任用。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年三月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0fec2eea-dddb-56ae-94d9-fb3c17d7840e"}, {"title": "明廷改封敷惠王并命奉祀懿文太子", "description": "朝廷将本纪所称敷惠王允𤐤改封为瓯宁王，命他奉祀懿文太子。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年三月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5fc19fde-9b1f-563a-a2e7-563cf6af666c"}, {"title": "明廷设置东宫官属", "description": "四月初一，朝廷设置东宫官属。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年四月辛未朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8d1cebea-f121-5c52-a2ae-a450e97519c1"}, {"title": "道衍被任为太子少师并赐名广孝", "description": "僧人道衍被任为太子少师，恢复姚姓，获赐名广孝。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年四月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2cb7bd4c-e391-574a-b0c9-617116c37c79"}, {"title": "朱棣册立朱高炽为皇太子", "description": "朱棣立儿子朱高炽为皇太子，同时封朱高煦为汉王、朱高燧为赵王。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年四月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c87e8a77-7815-57c2-b44c-1f6c0b5f83ff"}, {"title": "明廷册封琉球山南王", "description": "朝廷册封本纪所作汪应祖为琉球国山南王。卷末校记指出，本书《琉球传》写作王应祖。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年四月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "51dad3e4-4381-5115-b051-f84a12a94521"}, {"title": "李彬镇守广东，王友率水军巡海", "description": "丰城侯李彬镇守广东，清远伯王友担任总兵官，率领水军巡视海上。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年五月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1d9c74f7-e1c3-52b9-82b6-bbde423f8ff9"}, {"title": "明廷裁减冗官", "description": "朝廷下令裁减多余官员。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年六月丁亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "598dad24-927c-5ecc-8a98-4eb0c0067fa3"}, {"title": "明廷赈济松江嘉兴苏州湖州饥荒", "description": "朝廷下令赈济松江、嘉兴、苏州和湖州的饥荒。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年六月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "78352b32-91b8-566f-86aa-4d3e7987afeb"}, {"title": "安克帖木儿获封忠顺王", "description": "朝廷册封哈密安克帖木儿为忠顺王。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年六月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ba4436a2-0144-586e-9222-debd6aae5660"}, {"title": "朝廷杖责上书的鄱阳人并毁去书稿", "description": "一名鄱阳人上书，本纪称其毁谤先贤。朝廷以杖刑责罚此人并毁去所上书稿。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年七月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bdcc02cd-65e7-59c6-b51d-5f1fdc329162"}, {"title": "明廷赈济江西和湖广水灾", "description": "江西和湖广发生水灾，朝廷下令赈济。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年七月丙寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "be6bb040-6113-5af5-afba-1918e2598837"}, {"title": "天平从安南来投明廷", "description": "本纪记载，八月丁酉天平从安南来投，称其为故安南国王陈日煃之弟。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年八月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "00c1a03b-05e0-53cf-a819-574964368f6e"}, {"title": "周王来朝献驺虞，朱棣答复群臣祝贺", "description": "周王朱橚来朝，献上本纪所称驺虞。百官请求庆贺。朱棣说，祥瑞取决于德行，此物若真是祥瑞，更应修身反省。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年九月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "18be64ff-cdff-5cc4-9f28-c0d792bbcf8c"}, {"title": "朝廷迁山西一万户民众到北京", "description": "朝廷从山西迁一万户百姓到北京。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年九月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "66fc7560-af47-5419-bb9d-4fbd93614c54"}, {"title": "明廷要求御史据实考察官吏", "description": "朝廷命巡行御史监察官吏时避免仅凭传闻，按实际事迹报告官吏的表现。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0d32490d-76ed-5991-b0e7-f1a05755a8b0"}, {"title": "黄河在开封决口", "description": "本纪记载，黄河于十月丁丑在开封决口。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年十月丁丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8dae553a-024c-56ae-8e81-829393ad2291"}, {"title": "本纪记蒲城河津黄河水清", "description": "本纪记载，十月乙酉蒲城和河津一带的黄河水清。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年十月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b26a454f-c187-5a80-bc74-404743b01be1"}, {"title": "耿炳文家产被登记查抄，耿炳文自杀", "description": "本纪记载，这个月朝廷登记查抄长兴侯耿炳文的家产，耿炳文自杀。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "48a23c10-428e-5e98-9626-3d24ebf6ee63"}, {"title": "朱棣在奉天门复查囚案", "description": "朱棣在奉天门听取囚犯案件并复查。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年十一月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e1d16ac9-a361-540a-a9db-93e39031156c"}, {"title": "京师济南开封地震，朱棣命群臣反省", "description": "京师、济南和开封发生地震，朱棣敕令群臣修身反省。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年十一月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c903780c-dd91-5ffe-818c-7ea9c5c5b9f1"}, {"title": "明廷免征苏松嘉湖杭水灾地区田租", "description": "明廷免去苏州、松江、嘉兴、湖州和杭州受水灾地的田租。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年十一月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "12e0052e-5115-5715-9901-dd6059fd21e2"}, {"title": "本纪记同州韩城黄河水清", "description": "本纪记载，十二月壬辰同州和韩城一带的黄河水清。", "start_year": 1405, "end_year": 1405, "time_original": "永乐二年十二月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ab8584a2-c97c-57fe-997b-4e88d30272d3"}, {"title": "李景隆被关押入狱", "description": "本纪记载，这个月朝廷将李景隆关押入狱。", "start_year": 1405, "end_year": 1405, "time_original": "永乐二年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5eafa16e-a747-5771-ba48-1a5bc2309eba"}, {"title": "占城等地向明廷入贡", "description": "本纪记载，这一年占城、别失八里、琉球山北及山南、爪哇、真腊来贡。暹罗、日本及琉球中山来贡两次。 按原历纪年，事情发生在公元1404至1405年之间。", "start_year": null, "end_year": null, "time_original": "永乐二年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "73f593a0-e99d-5714-94b0-ec224de40017"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

